-- Transactional business events; no remote telemetry or cross-service foreign keys.
CREATE TABLE community.event_outbox(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,event_type text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version text NOT NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),correlation_id text NOT NULL);
CREATE TABLE community.event_outbox_delivery(event_id uuid NOT NULL REFERENCES community.event_outbox ON DELETE CASCADE,target text NOT NULL CHECK(target IN ('identidad','aprendizaje','comunidad','evidencias')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','retry','delivered','deadletter')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,delivered_at timestamptz,last_error text,PRIMARY KEY(event_id,target));
CREATE INDEX event_delivery_due_idx ON community.event_outbox_delivery(available_at,event_id) WHERE status IN ('pending','retry','processing');
CREATE TABLE community.event_inbox(source text NOT NULL,event_id uuid NOT NULL,source_sequence bigint NOT NULL,event_type text NOT NULL,request_hash char(64) NOT NULL,correlation_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(source,event_id));
CREATE TABLE community.event_projection(source text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,source_sequence bigint NOT NULL,aggregate_version text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,correlation_id text NOT NULL,PRIMARY KEY(source,aggregate_type,aggregate_id));
CREATE FUNCTION community.emit_domain_event(event_type text,aggregate_type text,aggregate_id uuid,aggregate_version text,payload jsonb) RETURNS void LANGUAGE plpgsql AS $$ DECLARE event_uuid uuid; BEGIN
 INSERT INTO community.event_outbox(event_type,aggregate_type,aggregate_id,aggregate_version,payload,correlation_id) VALUES(event_type,aggregate_type,aggregate_id,aggregate_version,payload,COALESCE(NULLIF(current_setting('app.correlation_id',true),''),gen_random_uuid()::text)) RETURNING event_id INTO event_uuid;
 INSERT INTO community.event_outbox_delivery(event_id,target) SELECT event_uuid,target FROM unnest(ARRAY['identidad','aprendizaje','evidencias']) target;
END $$;
CREATE FUNCTION community.membership_business_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM community.emit_domain_event('membership.changed','membership',(substr(md5(NEW.grupo_id::text||NEW.cuenta_id::text),1,12)||'5'||substr(md5(NEW.grupo_id::text||NEW.cuenta_id::text),14,3)||'8'||substr(md5(NEW.grupo_id::text||NEW.cuenta_id::text),18,15))::uuid,COALESCE(NEW.retirado_en,NEW.unido_en,clock_timestamp())::text,jsonb_build_object('accountId',NEW.cuenta_id,'groupId',NEW.grupo_id,'role',NEW.funcion,'state',NEW.estado)); RETURN NEW; END $$;
CREATE TRIGGER membership_business_event AFTER INSERT OR UPDATE ON community.membresia_grupo FOR EACH ROW EXECUTE FUNCTION community.membership_business_event();
CREATE FUNCTION community.reservation_business_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM community.emit_domain_event('reservation.changed','reservation',NEW.reserva_id,NEW.version::text,jsonb_build_object('reservationId',NEW.reserva_id,'workspaceId',NEW.espacio_id,'accountId',NEW.creada_por,'version',NEW.version,'state',NEW.estado)); RETURN NEW; END $$;
CREATE TRIGGER reservation_business_event AFTER INSERT OR UPDATE ON community.reserva FOR EACH ROW EXECUTE FUNCTION community.reservation_business_event();
GRANT SELECT,INSERT,UPDATE,DELETE ON community.event_outbox,community.event_outbox_delivery,community.event_inbox,community.event_projection TO community_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA community TO community_app;
